     1→const calculateCircleProgress = (value) => {
     2→  let radius = 40;
     3→  let c = Math.PI * (radius * 2);
     4→
     5→  if (value < 0) value = 0;
     6→  if (value > 100) value = 100;
     7→
     8→  let percentage = ((100 - value) / 100) * c;
     9→  return percentage;
    10→};
