     1→const axios = require("axios");
     2→
     3→const renderError = (message) => {
     4→  return `
     5→    <svg width="495" height="100" viewBox="0 0 495 100" fill="none" xmlns="http://www.w3.org/2000/svg">
     6→    <style>
     7→    .text { font: 600 16px 'Segoe UI', Ubuntu, Sans-Serif; fill: #2F80ED }
     8→    .small { font: 600 12px 'Segoe UI', Ubuntu, Sans-Serif; fill: #252525 }
     9→    </style>
    10→    <rect x="0.5" y="0.5" width="494" height="99%" rx="4.5" fill="#FFFEFE" stroke="#E4E2E2"/>
    11→    <text x="25" y="45" class="text">Something went wrong! file an issue at https://git.io/JJmN9</text>
    12→    <text id="message" x="25" y="65" class="text small">${message}</text>
    13→    </svg>
    14→  `;
    15→};
    16→
    17→// https://stackoverflow.com/a/48073476/10629172
    18→function encodeHTML(str) {
    19→  return str.replace(/[\u00A0-\u9999<>&](?!#)/gim, function (i) {
    20→    return "&#" + i.charCodeAt(0) + ";";
    21→  });
    22→}
    23→
    24→function kFormatter(num) {
    25→  return Math.abs(num) > 999
    26→    ? Math.sign(num) * (Math.abs(num) / 1000).toFixed(1) + "k"
    27→    : Math.sign(num) * Math.abs(num);
    28→}
    29→
    30→function isValidHexColor(hexColor) {
    31→  return new RegExp(
    32→    /^([A-Fa-f0-9]{8}|[A-Fa-f0-9]{6}|[A-Fa-f0-9]{3}|[A-Fa-f0-9]{4})$/
    33→  ).test(hexColor);
    34→}
    35→
    36→function parseBoolean(value) {
    37→  if (value === "true") {
    38→    return true;
    39→  } else if (value === "false") {
    40→    return false;
    41→  } else {
    42→    return value;
    43→  }
    44→}
    45→
    46→function fallbackColor(color, fallbackColor) {
    47→  return (isValidHexColor(color) && `#${color}`) || fallbackColor;
    48→}
    49→
    50→function request(data, headers) {
    51→  return axios({
    52→    url: "https://api.github.com/graphql",
    53→    method: "post",
    54→    headers,
    55→    data,
    56→  });
    57→}
    58→
    59→/**
    60→ *
    61→ * @param {String[]} items
    62→ * @param {Number} gap
    63→ * @param {string} direction
    64→ *
    65→ * @description
    66→ * Auto layout utility, allows us to layout things
    67→ * vertically or horizontally with proper gaping
    68→ */
    69→function FlexLayout({ items, gap, direction }) {
    70→  // filter() for filtering out empty strings
    71→  return items.filter(Boolean).map((item, i) => {
    72→    let transform = `translate(${gap * i}, 0)`;
    73→    if (direction === "column") {
    74→      transform = `translate(0, ${gap * i})`;
    75→    }
    76→    return `<g transform="${transform}">${item}</g>`;
    77→  });
    78→}
    79→
    80→module.exports = {
    81→  renderError,
    82→  kFormatter,
    83→  encodeHTML,
    84→  isValidHexColor,
    85→  request,
    86→  parseBoolean,
    87→  fallbackColor,
    88→  FlexLayout,
    89→};
